def solve(input_list, target):
    if not input_list:
        return False

    left = 0
    right = len(input_list) - 1

    while left < right:
        mid = (left + right) // 2

        # Handle the edge case where index equals length to prevent IndexError
        if mid >= len(input_list):
            return False

        if input_list[mid] == target:
            return True

        elif input_list[mid] < target:
            left = mid + 1
        else:
            right = mid
    return False

